const CAUSAS=[{"id":"pellets-cercal-alentejo","t":"\"We can't breathe\": pellet factory in Cercal do Alentejo","loc":"Cercal do Alentejo, Santiago do Cacém","reg":"Alentejo","cat":"infraestrutura","catLabel":"Industrial infrastructure","est":"urgente","status":"⚡ Fire contained · Opposition continues","prazo":false,"verif":"2026-08-21","quem":["Movimento Juntos pelo Cercal"],"res":"A fire at a pellet factory, active for ten days, exposed the community to toxic smoke and reignited opposition to the plant built next to the village.","img":"https://causasderaiz.org/pellets-cercal-alentejo.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT126539","petLabel":"⚡ Sign the petition →","ll":[37.8114,-8.6811],"num":1,"cat2":"poluicao","kw":["air pollution","toxic smoke","air quality","environmental pollution"]},{"id":"jardins-se-porto","t":"\"Not even the Cathedral is safe?\": petition to preserve the Diocese gardens on Porto's Sé hill","loc":"Sé hill, Porto","reg":"North","cat":"imobiliario","catLabel":"Heritage and urban green space","est":"urgente","status":"⚡ Council wants to refuse it","prazo":false,"verif":"2026-09-07","quem":["Public petition"],"res":"A public petition calls for the preservation of the Major Seminary gardens, threatened by a project approved as \"monastic accommodation\" and changed into a 3-star hotel.","img":"https://causasderaiz.org/jardins-se-porto.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT132421","petLabel":"⚡ Sign the petition →","ll":[41.1435,-8.6111],"num":2},{"id":"agueda-eucaliptos","t":"Águeda: Quercus reports new eucalyptus plantations in burned areas and calls for permits to be revoked","loc":"Águeda municipality, Aveiro district","reg":"Centre","cat":"incendios","catLabel":"Wildfires","est":"urgente","status":"⚡ Quercus demands ICNF revoke the permits","prazo":false,"verif":"2026-08-24","quem":["Quercus - Aveiro Regional Branch","Águeda Municipal Council"],"res":"Quercus is reporting new eucalyptus plantations next to homes, watercourses and roads in areas of Águeda hit by wildfires, including a plot next to the home of a victim of the September 2024 fire. The association is demanding ICNF revoke the reforestation permits, arguing they may breach the Municipal Master Plan; the Council accuses the institute of ignoring the municipality's restrictions for years.","img":"https://causasderaiz.org/agueda-eucaliptos.jpg?v=1","pet":"","petLabel":"","ll":[40.5754,-8.446],"num":3},{"id":"meco-sesimbra-agua-turismo","t":"Aldeia do Meco: water scarcity sharpens opposition to large tourism projects in Sesimbra","loc":"Aldeia do Meco, Sesimbra, Setúbal district","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Tourism + water scarcity","est":"urgente","status":"⚡ Petition demands permit revocation over salinization risk","prazo":false,"verif":"2026-09-13","quem":["Aldeia do Meco residents"],"res":"Since 2021, residents of Aldeia do Meco have opposed four large tourism projects, including TURIMECO's \"Pinhal do Atlântico\" aparthotel, with 411 units and 1,168 beds, which together plan around 600 dwellings and over 1,800 beds for a village with just over 300 inhabitants, in an area classified as a Site of Community Importance (Arrábida/Espichel). A new petition demands an embargo and revocation of these developments' licences over the risk of salinizing the aquifer: according to official environment agency data cited in the petition, the water exploitation index in the coastal sub-basins between the Tagus and Sado reaches 93% in September, with the piezometric level of the Tagus/Left Bank basin already below the 20th percentile.","img":"https://causasderaiz.org/meco-sesimbra-agua-turismo.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=aguaemsesimbra","petLabel":"⚡ Sign the petition →","ll":[38.463,-9.207],"num":4},{"id":"artilharia-um-campolide","t":"Artilharia Um: Campolide residents contest 683-home project exempted from environmental review","loc":"Rua de Artilharia Um, Campolide, Lisbon","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"urgente","status":"⚡ Complaint to the European Commission · Petition before the Municipal Assembly","prazo":false,"verif":"2026-09-03","quem":["Artilharia Um Movement"],"res":"A real-estate project of seven plots and 683 housing units on five hectares of the former Artilharia Um barracks in Campolide, developed by Novo Banco, was exempted from Environmental Impact Assessment despite exceeding the legal 500-unit threshold. The Artilharia Um Movement took the case to the Public Prosecutor's Office and filed a complaint with the European Commission against the Portuguese State for an alleged breach of the EU environmental impact assessment directive; the residents' petition is being reviewed by Lisbon's Municipal Assembly.","img":"https://causasderaiz.org/artilharia-um-campolide.jpg?v=1","pet":"https://peticaopublica.com/?pi=artilharia-um","petLabel":"⚡ Sign the petition →","ll":[38.735,-9.165],"num":5},{"id":"penajoia-almada","t":"Bairro da Penajóia: Cape Verdean, Angolan and Guinean families evicted without rehousing in Almada","loc":"Penajóia, Monte da Caparica, Almada","reg":"Lisbon and Tagus Valley","cat":"racismo-ambiental","catLabel":"Environmental racism","est":"urgente","status":"⚡ Demolitions continue · IHRU promises no eviction without a housing solution","prazo":false,"verif":"2026-08-21","quem":["Bairro Penajóia Residents Association and Vida Justa movement"],"res":"About 350 people from Portuguese-speaking African countries, 60 of them children, live on state-owned land without public electricity, water or sanitation in Almada, while demolitions without rehousing continue.","img":"https://causasderaiz.org/penajoia-almada.jpg?v=1","pet":"","petLabel":"","ll":[38.65,-9.19],"num":6},{"id":"pedreiras-beja","t":"Bairro das Pedreiras: Roma community has lived without water or sanitation for two decades in Beja","loc":"Bairro das Pedreiras, Beja, Baixo Alentejo","reg":"Alentejo","cat":"racismo-ambiental","catLabel":"Environmental racism","est":"urgente","status":"⚡ No structural response · Council carried out a new survey in 2025","prazo":false,"verif":"2026-08-21","quem":["Bairro das Pedreiras community"],"res":"About a thousand people, over 200 children among them, have lived since 2005 in a neighbourhood without piped water or basic sanitation, next to a kennel and Beja City Council's materials yard.","img":"https://causasderaiz.org/pedreiras-beja.jpg?v=1","pet":"","petLabel":"","ll":[38.02,-7.86],"num":7},{"id":"girabolhos","t":"Girabolhos Dam","loc":"Mondego River, Seia/Gouveia, Serra da Estrela","reg":"Centre","cat":"agua","catLabel":"Dam","est":"urgente","status":"⚡ Tender launched","prazo":false,"verif":"2026-08-21","quem":["GEOTA"],"res":"The dam presented as a flood response would not have prevented the very floods used to justify it.","img":"https://causasderaiz.org/girabolhos.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=geota-rios-livres","petLabel":"⚡ Sign the petition →","ll":[40.4189,-7.7028],"num":8},{"id":"biometano-torres-novas","t":"Gasdaterra biomethane plant next to Árgea, Torres Novas","loc":"Árgea, Torres Novas, Médio Tejo","reg":"Centre","cat":"infraestrutura","catLabel":"Industrial infrastructure","est":"urgente","status":"⚡ Consultation: 414 of 429 submissions against · Municipal Assembly unites against the project","prazo":false,"verif":"2026-09-03","quem":["Árgea Residents Commission"],"res":"An 18-million-euro investment to treat around 98,000 tonnes of waste a year next to a village mobilised residents, local councillors and the Municipal Assembly. Residents also object to the risk of bad odours and well contamination. The public consultation logged 429 submissions, 414 of them against the project; the council also points to planning and road-access obstacles, since the plant has no basis in the current Municipal Master Plan.","img":"https://causasderaiz.org/biometano-torres-novas.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT131272","petLabel":"⚡ Sign the petition →","ll":[39.4772,-8.5378],"num":9,"cat2":"poluicao","kw":["bad smell","odour","odor","environmental pollution","air pollution","biogas"]},{"id":"sintra-cascais","t":"Against the Urbanization of Sintra-Cascais Natural Park","loc":"Sintra, Lisbon district","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"urgente","status":"⚡ Active petition","prazo":false,"verif":"2026-09-13","quem":["Finis Terrae"],"res":"Sintra's Master Plan revision opens the way to densification inside a Natural Park and World Heritage Site. The petition combines online and paper signatures.","img":"https://causasderaiz.org/sintra-cascais.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT132295","petLabel":"⚡ Sign the petition →","ll":[38.8029,-9.3817],"num":10},{"id":"costa-terra-melides","t":"Costa Terra: luxury resort closes off public beaches in Melides","loc":"Melides, Grândola (coastline between Tróia and Melides)","reg":"Alentejo","cat":"praias","catLabel":"Beach access","est":"urgente","status":"⚡ Physical barriers unresolved · Quercus demands explanations (Aug 2026)","prazo":false,"verif":"2026-08-21","quem":["Dunas Livres Association","Quercus"],"res":"The luxury resort Costa Terra keeps private security and fencing restricting access to public beaches. An official inspection found seven beaches with conditioned access in Grândola; a year on, Quercus accuses the Government of hiding the fact that the barriers remain.","img":"https://causasderaiz.org/costa-terra-melides.jpg?v=1","pet":"https://peticaopublica.com/?pi=dunas-livres-troia","petLabel":"Sign the petition","ll":[38.155,-8.75],"num":11},{"id":"descontaminacao-ilha-terceira","t":"Decontamination of soils and aquifers on Terceira Island: nearly seven decades of contamination from Lajes Base","loc":"Terceira Island, Azores, next to Lajes Base","reg":"Azores","cat":"agua","catLabel":"Soil and aquifer contamination","est":"urgente","status":"⚡ Active petition · oversight committee created","prazo":false,"verif":"2026-08-21","quem":["Public petition","Azores Parliament"],"res":"Nearly seven decades of US military presence at Lajes Base left dozens of contaminated sites. Decontamination process stuck in a diplomatic deadlock.","img":"https://causasderaiz.org/descontaminacao-ilha-terceira.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=terceira","petLabel":"⚡ Sign the petition →","ll":[38.7333,-27.0833],"num":12,"cat2":"poluicao","kw":["contamination","environmental pollution","soil pollution","water pollution"]},{"id":"litoral-greenpeace","t":"Greenpeace warns a quarter of Portugal's coast is retreating and calls for a building moratorium","loc":"Continental coastline, especially Sesimbra and Grândola","reg":"National","cat":"sistemico","catLabel":"Coastline and climate change","est":"urgente","status":"⚡ Report and petition active","prazo":false,"verif":"2026-08-27","quem":["Greenpeace Portugal"],"res":"Greenpeace's \"Destruição a Toda a Costa\" report finds that 25% of Portugal's continental coastline is eroding and more than 100,000 people live in high-risk coastal areas. The organisation points to Sesimbra and Grândola as examples of outdated municipal plans licensing luxury tourism megaprojects in protected areas, and calls for a moratorium on construction in flood- or erosion-risk areas through 2050.","img":"https://causasderaiz.org/litoral-greenpeace.jpg?v=1","pet":"https://www.greenpeace.pt/como-ajudar/peticoes/litoral/","petLabel":"⚡ Sign the petition →","ll":null,"num":13},{"id":"marao","t":"Photovoltaic hybridization at Penedo Ruivo Wind Farm, Serra do Marão","loc":"Amarante and Baião, Serra do Marão","reg":"North","cat":"energia","catLabel":"Wind + solar","est":"urgente","status":"⚡ Unfavourable opinion","prazo":false,"verif":"2026-08-21","quem":["FAPAS"],"res":"Around 25,000 solar panels next to an existing wind farm, at 1,120–1,220 metres of altitude.","img":"https://causasderaiz.org/marao.jpg?v=1","pet":"https://peticaopublica.com/mobile/pview.aspx?pi=PT130242","petLabel":"⚡ Sign the petition →","ll":[41.2688,-8.0797],"num":14},{"id":"hyperion-abrantes","t":"Hyperion II: second data center advances next to the Pego power plant without a complete environmental impact study","loc":"Abrantes, next to the Pego power plant, Santarém district","reg":"Centre","cat":"datacenter","catLabel":"Data center","est":"urgente","status":"⚡ proTEJO demands cumulative EIA and water limits; combined consumption could reach 29x the municipality's annual electricity use","prazo":false,"verif":"2026-09-22","quem":["Abrantes Municipal Council","Quercus","proTEJO"],"res":"Second large-scale data center next to the Pego power plant, promoted by the Hyperion group, with 200 MVA of connection capacity and over 151,000 m² of footprint: the council unanimously approved the preliminary information request before a complete environmental impact study existed. Quercus warns that, added to the already-approved EDC ONE data center in the same municipality, combined consumption could reach about 1,314 GWh/year in a conservative scenario (nearly 9 times Abrantes' annual electricity use), or up to 29 times at maximum capacity, in a Tagus basin already facing a projected 40% water scarcity index for 2028-2033; the association demands a cumulative EIA that also assesses noise pollution and the heat-island effect.","img":"https://causasderaiz.org/hyperion-abrantes.jpg?v=1","pet":"","petLabel":"","ll":[39.42,-8.017],"num":15,"cat2":"poluicao","kw":["noise pollution","noise","heat island","water pollution","environmental pollution"]},{"id":"incineradora-algarve","t":"Waste incinerator in the Algarve: Government moves ahead despite environmentalist opposition","loc":"Algarve (site to be defined, to address the exhaustion of the Portimão and Loulé landfills)","reg":"Algarve","cat":"poluicao","catLabel":"Waste incineration","est":"urgente","status":"⚡ Quercus and Zero object · APA tender expected 15 October","prazo":false,"verif":"2026-09-06","quem":["Quercus","Zero"],"res":"Environment and Energy Minister Maria da Graça Carvalho announced on 8 August the construction of a waste-to-energy plant in the Algarve, with investment of up to €300 million and start-up expected in 2034, to address the exhaustion of the Portimão and Loulé landfills, projected for around 2027. The Algarve produces more waste per capita than any other region in the country (400,000 tonnes/year, 85% landfilled), driven largely by seasonal tourism. Quercus calls incineration \"completely anachronistic\", incompatible with the PERSU 2030 targets and the country's climate commitments (the technology emits more CO₂ per kWh than fossil fuels), and demands the Government publish the alternatives study it commissioned from consultancy Ramboll; the Portuguese Environment Agency will launch a tender on 15 October to study technology and siting.","img":"https://causasderaiz.org/incineradora-algarve.jpg?v=1","pet":"","petLabel":"","ll":null,"num":16,"kw":["incineration","air pollution","emissions","waste","environmental pollution"]},{"id":"matosinhos-ribeira-leca","t":"Matosinhos: polluting discharges and foul smells threaten the Leça river and bathing beaches","loc":"Leça river and streams of Leça da Palmeira and Matosinhos","reg":"North","cat":"poluicao","catLabel":"Industrial pollution and water contamination","est":"urgente","status":"⚡ Matosinhos beach at risk of losing its official bathing-water status · Councillors demand inspections","prazo":false,"verif":"2026-09-06","quem":["Matosinhos Municipal Council","PSD and Chega councillors"],"res":"Polluting discharges from the area of Galp's former refinery in Leça da Palmeira left a \"nauseating smell\" affecting the city in April; the Portuguese Environment Agency is now pursuing a fine against Galp. The problem runs deeper: around 900 illegal connections dump wastewater directly into the Riguinha and Carcavelos streams and the Leça river, and episodes of microbiological contamination have already led to temporary bathing bans at Matosinhos beach, which risks losing its official \"Bathing Water\" status. In August, PSD and Chega councillors demanded the council adopt an integrated plan to restore the streams, inspect illegal connections, and monitor water quality publicly in real time.","img":"https://causasderaiz.org/matosinhos-ribeira-leca.jpg?v=1","pet":"","petLabel":"","ll":[41.1857,-8.7042],"num":17,"kw":["water pollution","foul smell","contamination","environmental pollution","illegal discharges"]},{"id":"meia-praia-lagos","t":"Meia Praia: citizens protest against two-hotel development in Lagos","loc":"Meia Praia, Lagos, Algarve","reg":"Algarve","cat":"imobiliario","catLabel":"Tourism in sensitive coastal area","est":"urgente","status":"⚡ Citizen protest · Council admits legal limits to blocking it","prazo":false,"verif":"2026-08-24","quem":["Salvar a Meia Praia civic movement"],"res":"About 50 people protested outside Lagos Council against the construction of two hotels and a tourist apartment block on 11,000 m² of Meia Praia, under a 1988 permit revised in 2008. The \"Salvar a Meia Praia\" movement is demanding a new environmental impact assessment, particularly of the lagoon basin on the site; the mayor says he cannot block the project if the developer meets the law, but confirms licensing is still conditional on the developer requalifying the basin.","img":"https://causasderaiz.org/meia-praia-lagos.jpg?v=1","pet":"","petLabel":"","ll":[37.118,-8.646],"num":18},{"id":"lagoa-salgada","t":"Lagoa Salgada Mine: petition seeks project cancellation","loc":"Grândola and Alcácer do Sal, Alentejo coast","reg":"Alentejo","cat":"mineracao","catLabel":"Copper, lead and zinc mining","est":"urgente","status":"⚡ Unfavourable ruling","prazo":false,"verif":"2026-08-21","quem":["Public petition"],"res":"€196 million investment to mine a polymetallic deposit, already refused an Environmental Impact Statement.","img":"https://causasderaiz.org/lagoa-salgada.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT125518","petLabel":"⚡ Sign the petition →","ll":[38.173,-8.569],"num":19},{"id":"mina-adagoi","t":"Lithium and feldspar mine at Project C-192 Adagoi","loc":"Capeludos and Bragado, Vila Pouca de Aguiar, Vila Real district","reg":"North","cat":"mineracao","catLabel":"Lithium and feldspar mining","est":"urgente","status":"⚡ Petition active","prazo":false,"verif":"2026-08-21","quem":["Vila Pouca de Aguiar residents"],"res":"The C-192 Adagoi concession, for quartz, feldspar and lithium, adds to other mining projects already putting the Barroso region under pressure.","img":"https://causasderaiz.org/mina-adagoi.jpg?v=1","pet":"https://peticaopublica.com/?pi=protecao-territorio","petLabel":"⚡ Sign the petition →","ll":[41.4964,-7.6486],"num":20},{"id":"mina-gudina","t":"Tungsten mine in A Gudiña threatens the Rabaçal river and Montesinho Natural Park","loc":"A Gudiña, Ourense, Galicia (Spain), 2 km from Vinhais, Bragança","reg":"North","cat":"mineracao","catLabel":"Cross-border mining","est":"urgente","status":"⚡ Binational protest · No cross-border assessment","prazo":false,"verif":"2026-08-21","quem":["Movimento UIVO"],"res":"An open-pit tungsten mine is moving forward 2 km from the border without the cross-border impact assessment required by law, threatening the water supply of 14 Portuguese villages.","img":"https://causasderaiz.org/mina-gudina.jpg?v=1","pet":"","petLabel":"","ll":[42.058,-7.116],"num":21},{"id":"mina-panasqueira","t":"Panasqueira Mines: risk of toxic contamination threatens the Zêzere River","loc":"Covilhã and Fundão, Beira Baixa","reg":"Centre","cat":"mineracao","catLabel":"Tin and tungsten mining","est":"urgente","status":"⚡ Quercus opposes environmental licence renewal · Water intake suspended for 6 months","prazo":false,"verif":"2026-09-03","quem":["Quercus"],"res":"A collapse at a century-old mine's tailings dam sent lead and arsenic into the Ribeira de Cebola, a tributary that feeds the Castelo de Bode reservoir, the main source of water treated by EPAL for around 3 million people in Greater Lisbon. On the day the public consultation on the mine's Environmental Licence (PCIP) renewal closed, Quercus backed MiningWatch Portugal's unfavourable technical opinion and is asking the Portuguese Environment Agency not to renew the licence without a scheduled, financially guaranteed closure plan; six months after the incident, the water intake remains suspended and monitoring results have not been published.","img":"https://causasderaiz.org/mina-panasqueira.jpg?v=1","pet":"","petLabel":"","ll":[40.1717,-7.7756],"num":22,"cat2":"poluicao","kw":["contamination","water pollution","heavy metals","environmental pollution"]},{"id":"rio-corgo-vila-real","t":"Fish kill in the Corgo River, Vila Real, after a probable abnormal wastewater discharge","loc":"Corgo River, Vila Real municipality, Trás-os-Montes","reg":"North","cat":"agua","catLabel":"Environmental disaster · Water pollution","est":"urgente","status":"⚡ Under APA investigation · Samples in laboratory analysis","prazo":false,"verif":"2026-08-21","quem":["Portuguese Environment Agency (APA)","SEPNA/GNR"],"res":"APA is investigating the death of dozens of fish in the Corgo River, Vila Real, after a probable abnormal wastewater discharge that entered through the stormwater network between 15 and 16 August 2026.","img":"https://causasderaiz.org/rio-corgo-vila-real.jpg?v=1","pet":"","petLabel":"","ll":[41.301,-7.744],"num":23,"cat2":"poluicao","kw":["water pollution","environmental pollution","polluting discharge"]},{"id":"trilhos-madeira","t":"No to the privatisation of Madeira's natural trails","loc":"Autonomous Region of Madeira","reg":"Madeira","cat":"imobiliario","catLabel":"Land-use planning","est":"urgente","status":"⚡ Petition active","prazo":false,"verif":"2026-08-21","quem":["Madeira residents"],"res":"The Regional Government handed management of access to iconic trails to a private security company, without public consultation, drawing opposition from citizens and the LIVRE party.","img":"https://causasderaiz.org/trilhos-madeira.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT125916","petLabel":"⚡ Sign the petition →","ll":[32.69,-16.95],"num":24},{"id":"costa-caparica-arvores","t":"Stop the tree felling in Costa da Caparica","loc":"Praça Padre Manuel Bernardes and Torre das Argolas, Costa da Caparica, Almada","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Urban deforestation","est":"urgente","status":"⚡ Residents count more felled trees than announced","prazo":false,"verif":"2026-09-06","quem":["Costa da Caparica residents"],"res":"A beach-access upgrade project in Costa da Caparica (phase 2), costing around €3 million, led Almada municipal council to announce the felling of 47 trees, but residents count 103 trees already cut or marked for felling in Praça Padre Manuel Bernardes and Torre das Argolas, including at least 23 in June alone. A public petition calls for an immediate halt to the felling of the 34 trees still marked, for the demolition of Praça dos Navegantes to stop, and for more transparency and dialogue with residents before the works proceed.","img":"https://causasderaiz.org/costa-caparica-arvores.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT132029","petLabel":"⚡ Sign the petition →","ll":[38.643,-9.222],"num":25},{"id":"campismo-gale","t":"Galé Campsite has been closed since 2021, with no reopening in sight","loc":"Melides, Grândola","reg":"Alentejo","cat":"comunidade","catLabel":"Predatory tourism","est":"urgente","status":"⚡ Closed since 2021 · no reopening announced","prazo":false,"verif":"2026-09-01","quem":["Reabrir a Galé","Dunas Livres Association"],"res":"The Galé campsite in Melides closed in October 2021 after being bought for around €25 million by Discovery Land Company, which plans to turn the site into the Costa Terra luxury resort. The Reabrir a Galé movement took a petition to Parliament and organised protests; Grândola's council says it cannot intervene since it is private investment. No confirmed reopening has been reported to date.","img":"https://causasderaiz.org/campismo-gale.jpg?v=1","pet":"","petLabel":"","ll":[38.1667,-8.7667],"num":26},{"id":"aranha-cavernicola-arrabida","t":"For the protection of the Frade cave spider and its habitat","loc":"Frade Cave, Sesimbra, Arrábida Natural Park","reg":"Lisbon and Tagus Valley","cat":"sistemico","catLabel":"Biodiversity","est":"urgente","status":"⚡ Petition active","prazo":false,"verif":"2026-08-21","quem":["Petition signatories"],"res":"Europe's smallest spider lives only in one cave in Arrábida and is classified as Critically Endangered. The biggest threat to its habitat is quarrying.","img":"https://causasderaiz.org/aranha-cavernicola-arrabida.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT130753","petLabel":"⚡ Sign the petition →","ll":[38.4444,-9.1006],"num":27},{"id":"fortes-ferreira-alentejo","t":"The right to breathe clean air in Fortes, Ferreira do Alentejo","loc":"Fortes, Ferreira do Alentejo, Beja district","reg":"Alentejo","cat":"infraestrutura","catLabel":"Industrial pollution","est":"urgente","status":"⚡ Petition active · July measurements above air quality limits","prazo":false,"verif":"2026-09-03","quem":["Amigos das Fortes Environmental Association"],"res":"The AZPO – Azeites de Portugal olive-pomace oil extraction plant, about 300 metres from the village of Fortes, has been accused for over a decade by residents and livestock farmers of polluting the air they breathe and the water their animals drink; the Portuguese Environment Agency has already confirmed unlicensed wastewater discharges, and a criminal case against the company was archived by the Public Prosecutor's Office for lack of evidence. Tired of waiting, the Amigos das Fortes Environmental Association bought its own monitoring equipment and recorded, between 24 and 29 July 2026, over 30 hours of volatile organic compound concentrations above acceptable limits, results it will hand over to the environment agency. Residents have launched a petition for the right to breathe clean air.","img":"https://causasderaiz.org/fortes-ferreira-alentejo.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT131002","petLabel":"⚡ Sign the petition →","ll":[38.014,-8.141],"num":28,"cat2":"poluicao","kw":["environmental pollution","air pollution","air quality","water pollution","volatile organic compounds"]},{"id":"pedreira-lajedo-santo-tirso","t":"For the permanent closure of the Lajedo quarry, Monte Córdova","loc":"Monte Córdova, Santo Tirso","reg":"North","cat":"mineracao","catLabel":"Quarries","est":"urgente","status":"⚡ Illegally reactivated · Petition active","prazo":false,"verif":"2026-08-21","quem":["Monte Córdova residents"],"res":"After more than a decade inactive, the Lajedo quarry was illegally reactivated and expanded into an ecological reserve zone, reigniting decades of residents' complaints.","img":"https://causasderaiz.org/pedreira-lajedo-santo-tirso.jpg?v=1","pet":"https://peticaopublica.com/?pi=pedreiralajedonao","petLabel":"⚡ Sign the petition →","ll":[41.3428,-8.4772],"num":29},{"id":"predios-madeira","t":"Petition against high-rise construction in Madeira admitted to Regional Assembly","loc":"Funchal, Madeira Island","reg":"Madeira","cat":"imobiliario","catLabel":"Land-use planning","est":"urgente","status":"⚡ Petition admitted to Madeira's Parliament · Moves to 3rd Environment Committee","prazo":false,"verif":"2026-09-07","quem":["Signatories of the \"Safeguard Madeira's Urban Model\" petition","Nuno Morna"],"res":"Over 1,700 citizens asked Madeira's regional parliament to block buildings up to 20 storeys high in Funchal, after the Regional Government defended revising the municipal master plan. The petition, led by former MP Nuno Morna, was formally admitted by Madeira's Legislative Assembly on 19 August and referred for review to the 3rd Standing Committee on Environment, Climate and Natural Resources, a procedural step that, its promoter stresses, does not yet mean the proposals have been accepted.","img":"https://causasderaiz.org/predios-madeira.jpg?v=1","pet":"","petLabel":"","ll":[32.6669,-16.9241],"num":30},{"id":"nordeste-vivo-mogadouro","t":"Planalto Mirandês: already over 1,500 hectares of solar panels","loc":"Mogadouro and Miranda do Douro, Planalto Mirandês","reg":"North","cat":"megasolares","catLabel":"Mass solar + wind","est":"urgente","status":"⚡ Mogadouro council opposes new solar plant · Petition active","prazo":false,"verif":"2026-09-06","quem":["Plataforma Nordeste Vivo"],"res":"Plataforma Nordeste Vivo is preparing legal injunctions after confirming that residents did not know the real scale of the megaprojects, between already-approved solar plants and 35 wind turbines 200 metres tall planned by Engie. Among them is the Planalto Solar Photovoltaic Plant, a €117 million, 307.83-hectare project in the parish of Travanca (Mogadouro): the public consultation closed with 246 submissions, and Mogadouro Municipal Council filed a formal position of disagreement, arguing the municipality already makes a significant contribution to national renewable output. A citizens' petition calls for the defence of Travanca and the wider municipality.","img":"https://causasderaiz.org/nordeste-vivo.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT131073","petLabel":"⚡ Sign the petition →","ll":[41.3406,-6.7136],"num":31},{"id":"sao-luis-odemira","t":"For a sustainable future for São Luís, Odemira","loc":"São Luís, Odemira, Poldreiros do Meio / Lameiros","reg":"Alentejo","cat":"energia","catLabel":"Mass solar and wind plants","est":"urgente","status":"⚡ Petition active","prazo":false,"verif":"2026-08-21","quem":["Juntos por São Luís"],"res":"A mega photovoltaic plant covering 100 to 150 hectares inside the Natura 2000 network is mobilising the Juntos por São Luís movement, part of a national platform against megaprojects.","img":"https://causasderaiz.org/sao-luis-odemira.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT128742","petLabel":"⚡ Sign the petition →","ll":[37.7194,-8.63],"num":32},{"id":"eolico-penamacor-2","t":"Penamacor 2 wind farm revamp authorises felling of 755 protected trees","loc":"Serra de Santo André, Meimoa and Penamacor parishes, Castelo Branco district","reg":"Centre","cat":"eolicas","catLabel":"Wind farm re-equipment","est":"urgente","status":"⚡ Government authorises felling of 755 cork and holm oaks · Petition seeks revocation","prazo":false,"verif":"2026-09-07","quem":["Public petition signatories"],"res":"Through Order (Despacho) No. 775/2026, the Government authorised the felling of 451 cork oaks and 304 holm oaks (755 protected trees) on the Serra de Santo André, for the re-equipment of the Penamacor 2 wind farm: Lestenergia will replace seven old turbines with four more powerful ones, raising annual output from 23.48 to 88.44 GWh. The Portuguese Environment Agency waived the project from a full environmental impact assessment. A public petition demands the full revocation of the felling authorisation, an assessment of siting alternatives with less ecological impact, and stronger application of the mitigation hierarchy: avoid, minimise, and only then compensate for environmental damage.","img":"https://causasderaiz.org/eolico-penamacor-2.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT129537","petLabel":"⚡ Sign the petition →","ll":[40.15,-7.29],"num":33,"kw":["felling of protected trees","cork oaks","holm oaks"]},{"id":"sophia-beira","t":"Sophia and Beira: petition seeks suspension of both mega solar plants","loc":"Fundão, Penamacor and Idanha-a-Nova, Beira Baixa","reg":"Centre","cat":"megasolares","catLabel":"Mega solar plant","est":"urgente","status":"◐ Beira cancelled by developer (14 Sep 2026); Sophia still cut by 34%, redesign deadline 2 October","prazo":false,"verif":"2026-09-23","quem":["Platform Against the Beira Baixa Mega Solar Plants"],"res":"Two mega solar plants threaten 231 vertebrate species and over 1,158 hectares of montado in Beira Baixa. After a record public consultation with 12,693 submissions, developer Lightsource bp cut the Sophia project by 34% (from 867 to 573 MWp) and removed it from the area with the greatest irrigation potential; the redesigned project will go to a new public consultation in October 2026 and the plant is not expected to start operating before 2031.","img":"https://causasderaiz.org/sophia.jpg?v=1","pet":"https://participacao.parlamento.pt/initiatives/5569","petLabel":"⚡ Sign the petition →","ll":[40.1372,-7.5006],"num":34},{"id":"citrinos-alcacer-do-sal","t":"Tangerines in Alcácer do Sal: Quercus files complaint with the European Commission","loc":"Murta and Monte Novo estates, Alcácer do Sal, Alentejo coast","reg":"Alentejo","cat":"agua","catLabel":"Intensive agriculture","est":"urgente","status":"⚡ Complaint filed with the European Commission","prazo":false,"verif":"2026-08-21","quem":["Quercus"],"res":"A 295-hectare tangerine project in the Comporta/Galé Special Conservation Area was approved on its fourth attempt, despite 99.2% of public consultation input rejecting it.","img":"https://causasderaiz.org/citrinos-alcacer-do-sal.jpg?v=1","pet":"","petLabel":"","ll":[38.3,-8.6],"num":35},{"id":"eolico-mira-odemira","t":"Stop Galp's Mira Wind Project in Odemira","loc":"Odemira and Ourique, Beja district","reg":"Alentejo","cat":"eolicas","catLabel":"Wind and solar plant","est":"urgente","status":"⚡ Environmental impact assessment underway","prazo":false,"verif":"2026-09-06","quem":["Rural Odemira residents"],"res":"Galp is moving forward with 22 wind turbines (158 MW) and the hybridisation of a solar plant between Odemira and Ourique (18 of them in Odemira, affecting Relíquias, São Martinho das Amoreiras, Luzianes-Gare and Santa Clara-a-Velha), after its earlier Cachenas project was stopped by strong local opposition. Residents' petition denounces constant aerodynamic noise and shadow flicker from the blades near homes, on top of falling property values and a heightened wildfire risk from new access roads and high-voltage lines; the petition remains active, and Odemira Municipal Council is demanding public discussions in the affected parishes before anything moves forward.","img":"https://causasderaiz.org/eolico-mira-odemira.jpg?v=1","pet":"https://peticaopublica.com/?pi=PT131724","petLabel":"⚡ Sign the petition →","ll":[37.5975,-8.6383],"num":36,"cat2":"poluicao","kw":["noise","noise pollution","shadow flicker"]},{"id":"incendios","t":"2026 wildfire wave: Vouzela becomes Europe's largest fire of the year","loc":"North and Centre: Vouzela, Torre de Moncorvo, Valpaços, Mirandela, Águeda","reg":"North","cat":"incendios","catLabel":"Wildfires","est":"urgente","status":"⚡ Over 65,000 hectares burned by end of August","prazo":false,"verif":"2026-09-03","quem":["ICNF","AGIF"],"res":"Over 65,000 hectares burned by the end of August, 58% above the ten-year average. The Vouzela fire, which started on 2 July, is officially Europe's largest fire of 2026, accounting for around 70% of all area burned in the country.","img":"https://causasderaiz.org/incendios.jpg?v=1","pet":"","petLabel":"","ll":[40.75,-8.12],"num":37},{"id":"barragem-foupana","t":"Foupana Dam: new reservoir threatens the Algarve's last free-flowing stream","loc":"Castro Marim and Alcoutim, eastern Algarve","reg":"Algarve","cat":"agua","catLabel":"Dam","est":"consulta","status":"🗳 Public consultation until 12 October","prazo":false,"verif":"2026-09-09","quem":["Almargem"],"res":"Portugal's Environment Agency (APA) opened public consultation on the Environmental Impact Assessment for a new dam on the Foupana stream, promoted by the Eastern Algarve Irrigation Association, estimated to cost between 150 and 200 million euros. The NGO Almargem opposes the project, calling the Foupana \"the Algarve's last great free-flowing stream\" and habitat for the saramugo, a critically endangered fish; it notes the region's six existing dams already run below capacity and proposes alternatives such as wastewater reuse.","img":"https://causasderaiz.org/barragem-foupana.jpg?v=1","pet":"https://participa.pt/pt/consulta/barragem-da-foupana","petLabel":"🗳 Take part in the public consultation →","ll":[37.35,-7.62],"num":38},{"id":"biometano-abrigada-alenquer","t":"Gás da Terra biomethane plant in Marés, Abrigada (Alenquer)","loc":"Marés, Abrigada e Cabanas de Torres, Alenquer","reg":"Lisbon and Tagus Valley","cat":"infraestrutura","catLabel":"Industrial infrastructure","est":"consulta","status":"🗳 Public consultation until 15 September · Alenquer council issues unfavourable opinion (26 Aug)","prazo":false,"verif":"2026-09-03","quem":["Residents of Abrigada e Cabanas de Torres"],"res":"Gás da Terra wants to build a €20.5 million biomethane plant about 500 metres from homes in Marés, to process around 84,000 tonnes of agricultural and livestock waste a year. At a public meeting lasting almost three hours, residents rejected the project over fears of bad odours and heavier truck traffic; Alenquer municipal council issued an unfavourable opinion on 26 August. The public consultation runs on participa.pt until 15 September.","img":"https://causasderaiz.org/biometano-abrigada-alenquer.jpg?v=1","pet":"https://participa.pt/pt/consulta/uab-abrigada--unidade-de-producao-de-biometano-de-origem-renovavel-de-abrigada_185","petLabel":"🗳 Join the public consultation →","ll":[39.0719,-9.0017],"num":39,"cat2":"poluicao","kw":["bad smell","odour","odor","environmental pollution","biogas"]},{"id":"almaraz","t":"Almaraz: associations go to court against extending the Spanish nuclear plant","loc":"Almaraz, Cáceres, Spain (Tagus basin, 100 km from the Portuguese border)","reg":"National","cat":"energia","catLabel":"Cross-border nuclear plant","est":"tribunal","status":"⚖ Legal action announced","prazo":false,"verif":"2026-08-21","quem":["Iberian Energy Observatory","Adenex","Ecologistas en Acción","Greenpeace"],"res":"The Spanish government extended the Almaraz nuclear plant's operation until 2030, in the Tagus basin. Portuguese and Spanish associations are taking the decision to court.","img":"https://causasderaiz.org/almaraz.jpg?v=1","pet":"","petLabel":"","ll":[39.8083,-5.6969],"num":40},{"id":"talude-militar-loures","t":"Bairro do Talude Militar: a 40-year-old Cape Verdean and São Tomean community demolished without alternative in Loures","loc":"Talude Militar, Loures, Lisbon district","reg":"Lisbon and Tagus Valley","cat":"racismo-ambiental","catLabel":"Environmental racism","est":"tribunal","status":"⚖ Legal deadlock · 88 homes demolished, 23 protected by court injunction (Jul. 2026)","prazo":false,"verif":"2026-08-21","quem":["Vida Justa movement and Talude Militar residents"],"res":"A Cape Verdean and São Tomean community settled in Loures since the 1980s faces mass demolitions since July 2025. A year on, 88 homes have already been demolished and a legal deadlock leaves dozens of families without answers.","img":"https://causasderaiz.org/talude-militar-loures.jpg?v=1","pet":"","petLabel":"","ll":[38.83,-9.17],"num":41},{"id":"barragem-pisao","t":"Pisão Dam: works suspended for the third time by court order","loc":"Crato, Portalegre district, Alto Alentejo","reg":"Alentejo","cat":"agua","catLabel":"Dam","est":"tribunal","status":"⚖ Works suspended · Southern Central Administrative Court upheld suspension in May 2026","prazo":false,"verif":"2026-08-24","quem":["GEOTA","Quercus","LPN","ZERO"],"res":"A dam costing over €220 million that would submerge the village of Pisão. Four environmental associations have contested the project's public interest in court since 2022; public water supply would account for just over 1% of the reservoir's annual volume, against 65% for agricultural use. Works began in September 2025 and have been suspended and resumed several times; the Southern Central Administrative Court confirmed a new suspension in May 2026.","img":"https://causasderaiz.org/barragem-pisao.jpg?v=1","pet":"","petLabel":"","ll":[39.2897,-7.6644],"num":42},{"id":"fernando-pessoa","t":"Fernando Pessoa Solar Plant: Europe's largest keeps stalling in court","loc":"São Domingos, Santiago do Cacém, Alentejo coast","reg":"Alentejo","cat":"megasolares","catLabel":"Large-scale solar plant","est":"tribunal","status":"⚖ Licence suspended by court order","prazo":false,"verif":"2026-08-21","quem":["Public Prosecutor's Office","ProtegeAlentejo"],"res":"1,200 MW and 1.5 million trees to be felled for continental Europe's largest solar plant, its licence suspended by court order.","img":"https://causasderaiz.org/fernando-pessoa.jpg?v=1","pet":"","petLabel":"","ll":[37.93,-8.75],"num":43},{"id":"praias-arrabida","t":"Hands Off Arrábida: privatization of five beaches","loc":"Setúbal: Albarquel, Esguelha, Rainha, Comenda and Rasca beaches, Arrábida","reg":"Lisbon and Tagus Valley","cat":"praias","catLabel":"Beach access","est":"tribunal","status":"⚖ In court","prazo":false,"verif":"2026-09-03","quem":["Deslarrrguem a Arrábida! movement"],"res":"The company Palácio da Comenda is seeking private ownership of five beaches and a municipal road through the courts. The petition delivered to Parliament has gathered enough signatures for a parliamentary debate; the Public Prosecutor's Office and the Portuguese Environment Agency are also contesting the company's claim.","img":"https://causasderaiz.org/praias-arrabida.jpg?v=1","pet":"","petLabel":"","ll":[38.5244,-8.8882],"num":44},{"id":"dessalinizadora-albufeira","t":"Algarve desalination plant: works proceed in Albufeira amid new legal challenge","loc":"Praia da Rocha Baixinha / Olhos de Água, Albufeira","reg":"Algarve","cat":"agua","catLabel":"Desalination","est":"tribunal","status":"⚖ Works proceed · New injunction filed","prazo":false,"verif":"2026-08-21","quem":["Plataforma Água Sustentável","Seacliff"],"res":"Over 100 million euros to desalinate seawater in the Algarve. Already the target of two injunctions, still contested by environmentalists and fishers.","img":"https://causasderaiz.org/dessalinizadora-albufeira.jpg?v=1","pet":"","petLabel":"","ll":[37.114,-8.169],"num":45},{"id":"mina-borralha","t":"Borralha Mine: reactivated tungsten mining threatens Cávado water quality","loc":"Montalegre, Vila Real district","reg":"North","cat":"mineracao","catLabel":"Tungsten mining","est":"urgente","status":"⚡ Petition demands unfavourable EIS · Braga City Council warns of risk to Cávado (Sept 9) · Legal action ongoing","prazo":false,"verif":"2026-09-17","quem":["Povo e Natureza do Barroso","Cávado Sem Minas collective"],"res":"A petition by the Cávado Sem Minas collective calls on basin councils to reject the project, after Braga City Council warned of a risk to Cávado drinking water; six associations had already taken a tungsten mine's Environmental Impact Statement to court, in the Gerês-Xurés Biosphere Reserve.","img":"https://causasderaiz.org/mina-borralha.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT132877","petLabel":"⚡ Sign the petition →","ll":[41.752,-7.977],"num":46},{"id":"barroso","t":"Lithium mine in Covas do Barroso","loc":"Boticas, Vila Real, Barroso region","reg":"North","cat":"mineracao","catLabel":"Lithium mining","est":"tribunal","status":"⚖ Court suspends easement · Commoners reject Savannah's agreements (Aug 13)","prazo":false,"verif":"2026-09-19","quem":["Unidos em Defesa de Covas do Barroso"],"res":"Savannah Resources wants to open an open-pit mine in a centuries-old farming area. The Mirandela Administrative and Tax Court suspended the administrative easement granting access to the commons; on August 13, the Assembly of Commoners overwhelmingly rejected Savannah's attempt to present recent agreements as a sign of social acceptance of the project.","img":"https://causasderaiz.org/barroso.jpg?v=1","pet":"","petLabel":"","ll":[41.6897,-7.6772],"num":47},{"id":"pego-transicao-justa","t":"\"Just Transition\" at the Pego power plant: Gavião unanimously rejects PIN-status renewables project","loc":"Pego power plant, between Abrantes and Gavião, Centro/Alentejo","reg":"Centre","cat":"energia","catLabel":"Solar + wind + storage","est":"acompanhamento","status":"◐ Rejected by council, national PIN granted","prazo":false,"verif":"2026-09-19","quem":["Gavião Municipal Council"],"res":"A €700 million project combining solar, wind and storage on the site of the former Pego coal plant holds PIN status. Gavião rejected it unanimously, saying the municipality already has about 2% of its territory covered by renewables.","img":"https://causasderaiz.org/pego-transicao-justa.jpg?v=1","pet":"","petLabel":"","ll":[39.418,-8.015],"num":48},{"id":"ia-sines","t":"The Sines AI gigafactory: the energy, water and forests no one accounts for","loc":"Sines and Santiago do Cacém, Alentejo coast","reg":"Alentejo","cat":"datacenter","catLabel":"Data center","est":"acompanhamento","status":"◐ Legal dispute over seawater between EDP and the Government","prazo":false,"verif":"2026-08-24","quem":["TAMLA"],"res":"Behind \"technological sovereignty\" sits a legal fight over seawater and Europe's largest solar plant, forest felling included. Decree-Law 52/2026 transferred ownership of the seawater channels that cool EDP's data centre to Águas de Santo André; Start Campus admits the dispute could delay the €10 billion project.","img":"https://causasderaiz.org/ia-sines.jpg?v=1","pet":"","petLabel":"","ll":[37.9564,-8.8647],"num":49},{"id":"montijo-alcochete","t":"Montijo airport was stopped, but Alcochete advances with greater risks","loc":"Alcochete: firing range, over the Tejo-Sado aquifer","reg":"Lisbon and Tagus Valley","cat":"infraestrutura","catLabel":"Infrastructure","est":"acompanhamento","status":"◐ Alcochete moves forward","prazo":false,"verif":"2026-08-21","quem":["Quercus"],"res":"Lisbon's new airport moved to Alcochete, threatening over 250,000 cork oaks and the country's largest freshwater reserve.","img":"https://causasderaiz.org/montijo.jpg?v=1","pet":"","petLabel":"","ll":[38.755,-8.9581],"num":50},{"id":"castelo-bode","t":"Amara Village at Castelo de Bode","loc":"Tomar, shores of the Castelo de Bode reservoir","reg":"Centre","cat":"imobiliario","catLabel":"Real estate","est":"acompanhamento","status":"◐ No environmental assessment","prazo":false,"verif":"2026-08-21","quem":["Quercus"],"res":"A 50-hectare tourist resort on the country's second-largest reservoir, with no Environmental Impact Assessment.","img":"https://causasderaiz.org/castelo-bode.jpg?v=1","pet":"","petLabel":"","ll":[39.6033,-8.4106],"num":51},{"id":"rio-almansor","t":"AMORA: residents of Montemor-o-Novo organize to regenerate the Almansor River","loc":"Almansor River, Montemor-o-Novo, Alentejo","reg":"Alentejo","cat":"agua","catLabel":"River pollution and regeneration","est":"acompanhamento","status":"◐ Fine under appeal · Plan approved","prazo":false,"verif":"2026-08-21","quem":["AMORA (Almansor River Monitoring and Regeneration Association)"],"res":"The Almansor River has received decades of agricultural, livestock and sewage discharges that keep it rated \"Below Good\". Residents organized as AMORA already secured a water management plan unprecedented in the country.","img":"https://causasderaiz.org/rio-almansor.jpg?v=1","pet":"https://amoralmansor.pt/torne-se-socio/inscricao-de-socios/","petLabel":"⚡ Become an AMORA member →","ll":[38.6486,-8.2205],"num":52,"cat2":"poluicao","kw":["water pollution","environmental pollution","polluting discharges"]},{"id":"rio-eiriz-meixomil","t":"Sewage collector failure causes fish kill in the Eiriz River, Meixomil","loc":"Eiriz River, Meixomil, Paços de Ferreira, Porto district","reg":"North","cat":"agua","catLabel":"Environmental disaster · Water pollution","est":"acompanhamento","status":"◐ Cause identified · Clean-up underway","prazo":false,"verif":"2026-08-21","quem":["Meixomil Parish Council","Águas de Paços de Ferreira"],"res":"A sewage collector failure in the parish of Eiriz caused a polluting discharge that killed dozens of fish in the Eiriz River, next to the Meixomil Urban Park, in Paços de Ferreira.","img":"https://causasderaiz.org/rio-eiriz-meixomil.jpg?v=1","pet":"","petLabel":"","ll":[41.277,-8.353],"num":53,"cat2":"poluicao","kw":["water pollution","environmental pollution"]},{"id":"sobreiros-tortosendo","t":"Covilhã City Council wants to fell 1,400 cork oaks to expand the Tortosendo Industrial Park","loc":"Tortosendo, Covilhã","reg":"Centre","cat":"imobiliario","catLabel":"Deforestation for industrial expansion","est":"acompanhamento","status":"◐ Public discussion of the master plan closed 4 September · Council has not announced a decision","prazo":false,"verif":"2026-09-07","quem":["Quercus"],"res":"As part of the revision of the Municipal Master Plan (PDM), Covilhã City Council plans to fell around 1,400 cork oaks (dozens of them centuries old) for a third phase of the Tortosendo Industrial Park, an area that also includes two watercourses, three ponds, several springs and 10 primary residences that could face expropriation. Quercus calls the expansion a \"false pretext\", arguing that half the plots in the current industrial zone are empty or abandoned, and demands the council prove there is no viable alternative before removing a legally protected species. Mayor Hélio Fazendeiro says the expansion will comply with the law and include replanting; the public discussion closed on 4 September with no final decision announced.","img":"https://causasderaiz.org/sobreiros-tortosendo.jpg?v=1","pet":"","petLabel":"","ll":[40.255,-7.535],"num":54},{"id":"central-eolica-fronteira","t":"Fronteira Wind Farm: 35 turbines next to the Douro Internacional Natural Park","loc":"Avelanoso and Vimioso, hybridised with the Picote Hydroelectric Plant, Bragança district","reg":"North","cat":"eolicas","catLabel":"Large-scale wind farm","est":"acompanhamento","status":"◐ Public consultation closed on 17 August with 233 submissions","prazo":false,"verif":"2026-08-24","quem":["Miranda do Douro Municipal Council"],"res":"35 turbines and 157.5 MW of capacity, in a 5,893-hectare study area overlapping the Douro Internacional Natural Park and Natura 2000 sites. The public consultation closed on 17 August with 233 submissions recorded.","img":"https://causasderaiz.org/central-eolica-fronteira.jpg?v=1","pet":"","petLabel":"","ll":[41.6,-6.45],"num":55},{"id":"sobreira","t":"Sobreira de Baixo Photovoltaic Plant (EDP)","loc":"Pedrógão, Vidigueira, Évora district","reg":"Alentejo","cat":"megasolares","catLabel":"Mega solar plant","est":"acompanhamento","status":"◐ Construction planned Nov. 2026","prazo":false,"verif":"2026-08-21","quem":["LPN"],"res":"EDP's largest solar plant in Europe, with \"very significant\" impacts on Bonelli's eagle and protected bats.","img":"https://causasderaiz.org/sobreira.jpg?v=1","pet":"","petLabel":"","ll":[38.2039,-7.7975],"num":56},{"id":"hidrogenio-sines","t":"Green hydrogen and fuels cluster in Sines: five projects with PIN status","loc":"Sines, Alentejo coast","reg":"Alentejo","cat":"energia","catLabel":"Hydrogen and green fuels","est":"acompanhamento","status":"◐ 5 projects with PIN status","prazo":false,"verif":"2026-08-21","quem":["Business press research (ECO, AICEP data)"],"res":"Five projects tied to hydrogen, ammonia and synthetic fuels hold PIN status in Sines, part of the 13 projects in the \"chemical and petrochemical\" sector that, according to AICEP, represent the largest share of PIN projects alongside tourism.","img":"https://causasderaiz.org/hidrogenio-sines.jpg?v=1","pet":"","petLabel":"","ll":[37.9564,-8.8647],"num":57},{"id":"azambuja-dc","t":"Neoen data center in Alcoentre: Azambuja Council blocks PIN status request","loc":"Alcoentre, Azambuja, Lisbon district","reg":"Lisbon and Tagus Valley","cat":"datacenter","catLabel":"Data center","est":"acompanhamento","status":"◐ Unfavourable council opinion, PIN pending","prazo":false,"verif":"2026-09-03","quem":["Azambuja Municipal Council"],"res":"French company Neoen requested PIN status for a €2 billion data center in Alcoentre, just metres from hundreds of homes. Azambuja Council gave an unfavourable opinion, citing missing environmental, noise and landscape impact studies: the developers submitted no noise mitigation measures or guarantees of real benefits for the municipality. Opposition councillors walked out of an extraordinary meeting on the process, accusing the executive of sharing documentation only three working days before the vote.","img":"https://causasderaiz.org/azambuja-dc.jpg?v=1","pet":"","petLabel":"","ll":[39.183,-8.95],"num":59,"cat2":"poluicao","kw":["noise pollution","noise"]},{"id":"lagoas-acores","t":"Eutrophication of Azores lakes by intensive dairy farming","loc":"Lagoa das Furnas and Lagoa das Sete Cidades, São Miguel, Azores","reg":"Azores","cat":"agua","catLabel":"Freshwater + intensive farming","est":"acompanhamento","status":"◐ Structural problem","prazo":false,"verif":"2026-08-21","quem":["Regional Government of the Azores"],"res":"Intensifying dairy production is choking São Miguel's lakes with excess fertilizer and runoff.","img":"https://causasderaiz.org/lagoas-acores.jpg?v=1","pet":"","petLabel":"","ll":[37.7667,-25.3167],"num":60,"cat2":"poluicao","kw":["water pollution","environmental pollution","eutrophication"]},{"id":"monte-rei","t":"Expansion of the Monte Rei golf course amid a water emergency","loc":"Vila Nova de Cacela, Vila Real de Santo António, Algarve","reg":"Algarve","cat":"imobiliario","catLabel":"Real estate + water","est":"acompanhamento","status":"◐ Unfavourable opinion","prazo":false,"verif":"2026-08-21","quem":["ZERO"],"res":"A second 56-hectare golf course, called by ZERO \"incompatible with the water emergency\" facing the Algarve.","img":"https://causasderaiz.org/monterei.jpg?v=1","pet":"","petLabel":"","ll":[37.169,-7.546],"num":61},{"id":"linha-atalaia-cruzeiro-concavada","t":"Atalaia-Torre das Vargens power line and Cruzeiro-Concavada branch: public consultation in the Pego Cluster","loc":"Gavião, Abrantes and Ponte de Sor, in the Pego power plant area","reg":"Centre","cat":"energia","catLabel":"Interconnection power lines","est":"acompanhamento","status":"◐ Public consultation closed","prazo":false,"verif":"2026-08-24","quem":["CHIRO: Associação Morcegos.pt"],"res":"Environmental impact assessment (EIA no. 3736) of power lines in Endesa's Pego Cluster. CHIRO asked for bat monitoring before it proceeds; the public consultation has now closed.","img":"https://causasderaiz.org/linha-atalaia-cruzeiro-concavada.jpg?v=1","pet":"","petLabel":"","ll":[39.4,-8.05],"num":62},{"id":"movimento-meco-livre","t":"Meco Livre","loc":"Meco and Azóia, Sesimbra, Setúbal district","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Tourism in protected area","est":"acompanhamento","status":"◐ SOS Meco petition closed · Movement continues to denounce pine felling in protected area","prazo":false,"verif":"2026-09-13","quem":["Meco Livre Movement"],"res":"Associative movement against the destruction of Sesimbra's protected areas for the construction of tourism developments.","img":"https://causasderaiz.org/movimento-meco-livre.jpg?v=1","pet":"","petLabel":"","ll":[38.478,-9.204],"num":63,"kw":["deforestation","pine felling","pine forest","cumulative environmental impact assessment"]},{"id":"royal-china-clay-serra-del-rei","t":"Royal China Clay kaolin mine in Serra d'El-Rei","loc":"Serra d'El-Rei, Peniche, Leiria district","reg":"Centre","cat":"mineracao","catLabel":"Kaolin mining","est":"acompanhamento","status":"⚡ OesteCIM (12 municipalities) asks APA for an unfavourable environmental impact declaration (11 Sep 2026)","prazo":false,"verif":"2026-09-23","quem":["Mestres do Oceano","Coletivo Animal","Quercus"],"res":"The C-185 “Royal China Clay” mining concession, held by Motamineral – Minerais Industriais, would exploit 51.4 hectares of kaolinitic sands across three cores near Serra d'El-Rei (Peniche), with an on-site industrial washing plant. The public consultation closed on 1 September with 7,368 submissions; the councils of Óbidos and Peniche gave an unfavourable opinion on the project, and Quercus joined the call to reject it, warning of cumulative impacts on the region.","img":"https://causasderaiz.org/royal-china-clay-serra-del-rei.jpg?v=1","pet":"","petLabel":"","ll":[39.331,-9.27],"num":64},{"id":"mina-gaviao-aljustrel","t":"Gavião mine in Aljustrel: ZERO calls for the Almina project to be rejected","loc":"Aljustrel and Rio de Moinhos, Beja district","reg":"Alentejo","cat":"mineracao","catLabel":"Underground polymetallic mining","est":"acompanhamento","status":"◐ Public consultation closed on 31 August · ZERO calls for the project to be rejected","prazo":false,"verif":"2026-09-10","quem":["ZERO"],"res":"The C-14 “Gavião” mining concession, held by Almina – Minas do Alentejo, would exploit a new deposit of sulphur, iron, copper, lead, zinc, silver and gold next to the existing Aljustrel mine, with operations planned until 2050. The public consultation on the environmental impact study closed on 31 August; the ZERO association argues the project does not meet the conditions for approval, since it fails to assess a rail alternative for transporting the ore (even though Aljustrel's ore has been carried by train for decades), and does not present a destination for the millions of tonnes of waste to be produced after 2031.","img":"https://causasderaiz.org/mina-gaviao-aljustrel.jpg?v=1","pet":"","petLabel":"","ll":[37.8814,-8.1633],"num":65},{"id":"cais-carga-sines","t":"New General Cargo Dock at the Port of Sines: military use without public debate","loc":"Port of Sines, Alentejo coast","reg":"Alentejo","cat":"infraestrutura","catLabel":"Port infrastructure","est":"acompanhamento","status":"◐ Public consultation closed on 9 September · awaiting Environmental Impact Statement","prazo":false,"verif":"2026-09-10","quem":["Iniciativa Cidadã (Sines)","Left Bloc"],"res":"The Environmental Impact Study for the new General Cargo Dock at the Port of Sines, a €90 million investment, allows for \"dual\" civil and military use of the infrastructure. Iniciativa Cidadã, a Sines residents' group led by Eugénia Santa Bárbara and Bruno Candeias, said there had been no public information on the issue and organised a public meeting on 4 September; the Left Bloc questioned the government about a possible link to NATO's logistics network. The Administration of the Ports of Sines and the Algarve confirms \"dual-use requirements\" but denies a permanent military installation. The public consultation closed on 9 September, with the Portuguese Environment Agency yet to publish its Environmental Impact Statement.","img":"https://causasderaiz.org/cais-carga-sines.jpg?v=1","pet":"","petLabel":"","ll":[37.95,-8.8683],"num":66},{"id":"eolico-sudoeste-sines","t":"Southwest Wind Farm in Santiago do Cacém: Quercus warns of underassessed impacts","loc":"Santiago do Cacém and Cercal do Alentejo, Alentejo coast","reg":"Alentejo","cat":"eolicas","catLabel":"Large-scale wind farm","est":"acompanhamento","status":"◐ Public consultation on the assessment scope closed on 18 August","prazo":false,"verif":"2026-08-24","quem":["Quercus","RENOVAR Santiago do Cacém"],"res":"Up to 31 turbines and a lithium battery park across 1,098 hectares, to power the Sines Data Center that could eventually use 20% of the country's electricity. The public consultation on the scope of the environmental impact study closed on August 18; the full environmental impact study now follows.","img":"https://causasderaiz.org/eolico-sudoeste-sines.jpg?v=1","pet":"","petLabel":"","ll":[38.0128,-8.6975],"num":67},{"id":"parque-natural-arrabida","t":"Arrábida Natural Park: quarries, concrete and tourism close in on the most protected land near Lisbon","loc":"Serra da Arrábida: Sesimbra, Setúbal and Palmela","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"acompanhamento","status":"◐ Simultaneous pressure on several fronts, with no updated plan since the park was created","prazo":false,"verif":"2026-09-13","quem":["LPN","ZERO","Quercus","Arrábida - Natureza e Comunidade","Hands Off Arrábida Movement","Meco Livre Movement"],"res":"Created in 1976, Arrábida Natural Park protects 12,328 hectares and forms part of the Arrábida/Espichel Special Conservation Area (Natura 2000), with 32 protected habitat types. Yet no instrument today assesses the cumulative pressure surrounding it: 11 quarries already occupy 323 hectares inside the park (more than double the area in 1976, only two of which are being rehabilitated), including Secil's, which runs one of the country's largest cement plants there; a court case disputes public ownership of five beaches in Setúbal (\"Hands Off Arrábida!\"); the Forte Velho do Outão fort was granted as a 50-year concession to a hotel group; and four tourism megaprojects in Meco and Azóia, with over 4,000 planned beds, are moving forward without a cumulative Environmental Impact Assessment, despite sharing the same protected area, the reason behind the Meco Livre Movement's \"SOS Meco\" petition. The Frade cave spider, Europe's smallest and critically endangered, survives in a single cave in the range threatened by these same quarries. According to the association Arrábida - Natureza e Comunidade, the built-up area inside the park has grown by around 500% since the 1960s.","img":"https://causasderaiz.org/parque-natural-arrabida.jpg?v=1","pet":"","petLabel":"","ll":[38.48,-8.95],"num":68,"cat2":"mineracao","kw":["quarries","cement plant","concrete","tourism","biodiversity","land-use planning","beaches","cave spider"]},{"id":"arrabida","t":"Secil quarries in Arrábida Natural Park","loc":"Setúbal, Arrábida Natural Park","reg":"Lisbon and Tagus Valley","cat":"mineracao","catLabel":"Quarries","est":"acompanhamento","status":"◐ Demand made to company","prazo":false,"verif":"2026-08-21","quem":["LPN, among seven organisations"],"res":"Seven organizations demand Secil present a plan to decommission its quarries in a protected area.","img":"https://causasderaiz.org/arrabida.jpg?v=1","pet":"","petLabel":"","ll":[38.483,-8.977],"num":69},{"id":"borba","t":"Quarries with no environmental oversight: Borba and Vila Viçosa","loc":"Évora district","reg":"Alentejo","cat":"mineracao","catLabel":"Quarries","est":"acompanhamento","status":"◐ Reported","prazo":false,"verif":"2026-08-21","quem":["Independent survey"],"res":"232 registered quarries, over half with no valid environmental recovery plan.","img":"https://causasderaiz.org/pedreiras-borba.jpg?v=1","pet":"","petLabel":"","ll":[38.7994,-7.4548],"num":70},{"id":"restauro-natureza","t":"National Nature Restoration Plan: submitted to Brussels on 1 September","loc":"National: public consultation via the Participa Portal","reg":"National","cat":"sistemico","catLabel":"Nature restoration","est":"acompanhamento","status":"◐ Plan submitted to Brussels on 1 September · European Commission has 6 months to assess","prazo":false,"verif":"2026-09-03","quem":["Government public consultation","input from ZERO and SPEA"],"res":"€500 million a year and 386 measures to halt biodiversity loss across terrestrial, coastal, marine and urban ecosystems. The public consultation, from 9 July to 19 August, received 184 submissions; the Government delivered the Plan to the European Commission on 1 September, three days ahead of the deadline. Brussels now has six months to assess it, followed by a further six months for Portugal to publish the final version.","img":"https://causasderaiz.org/restauro-natureza.jpg?v=1","pet":"","petLabel":"","ll":null,"num":71},{"id":"poco-velho-aveiros-albufeira","t":"Poço Velho and Aveiros: two blocked-access beaches in Albufeira","loc":"Poço Velho and Aveiros, Albufeira, Algarve","reg":"Algarve","cat":"praias","catLabel":"Beach access","est":"acompanhamento","status":"◐ APA inspection confirmed blocked access (Oct 2025)","prazo":false,"verif":"2026-08-21","quem":["Portuguese Environment Agency"],"res":"An APA inspection of 29 Algarve beaches found public access to Poço Velho beach, in Albufeira, blocked by a gate on private land. Not an isolated case: nearby Praia dos Aveiros had already been closed off by an identical gate in 2014.","img":"https://causasderaiz.org/poco-velho-aveiros-albufeira.jpg?v=1","pet":"","petLabel":"","ll":[37.083,-8.283],"num":72},{"id":"quinta-dos-ingleses","t":"Quinta dos Ingleses: court rules on bid to halt 850-apartment development in the Carcavelos pine forest","loc":"Carcavelos, Cascais, Lisbon district","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"tribunal","status":"⚖ Works suspended by injunction · court hearings under way in September 2026","prazo":false,"verif":"2026-09-19","quem":["SOS Quinta dos Ingleses","66 Pela Quinta"],"res":"Cascais Municipal Council approved a detailed plan enabling around 850 apartments, a hotel and a shopping centre on a centuries-old, roughly 52-hectare pine forest next to Carcavelos beach. Since October 2025, a popular legal action by the 66 Pela Quinta movement has kept the works suspended under an injunction; the Sintra Administrative and Fiscal Court is holding trial hearings in September 2026.","img":"https://causasderaiz.org/quinta-dos-ingleses.jpg?v=1","pet":"","petLabel":"","ll":[38.687,-9.328],"num":73,"kw":["land-use planning","pine forest","popular legal action"]},{"id":"revive-forte-outao","t":"Revive: Forte Velho do Outão becomes a 50-year tourism concession inside the Natural Park","loc":"Forte Velho do Outão / 7th Outão Battery, Setúbal, Serra da Arrábida","reg":"Lisbon and Tagus Valley","cat":"infraestrutura","catLabel":"Tourism in protected area","est":"acompanhamento","status":"◐ Council approved conversion into hotel (Jan. 2025)","prazo":false,"verif":"2026-08-31","quem":["Press research (ECO, Publituris Hotelaria)"],"res":"Under the Revive programme, the Portuguese state granted a 50-year concession over the Forte Velho do Outão, a former coastal defence battery inside the Arrábida Natural Park, next to the Secil cement plant. The concession was awarded in 2023 to the catering company Real Bolhão, first for a restaurant; in January 2025 Setúbal City Council approved converting the project instead into a 5-star hotel with around 35 rooms. There is no public confirmation of works having started since then.","img":"https://causasderaiz.org/revive-forte-outao.jpg?v=1","pet":"","petLabel":"","ll":[38.481,-8.976],"num":75},{"id":"serta","t":"Sertã: over 25% of the municipality earmarked for solar acceleration zones","loc":"Sertã, Castelo Branco, Beira Baixa","reg":"Centre","cat":"megasolares","catLabel":"Solar acceleration zone","est":"acompanhamento","status":"◐ Unfavourable opinion","prazo":false,"verif":"2026-08-21","quem":["Sertã Municipal Council"],"res":"The City Council and the whole Beira Baixa region issued an unfavourable opinion on the acceleration zone programme.","img":"https://causasderaiz.org/serta.jpg?v=1","pet":"","petLabel":"","ll":[39.8,-8.0967],"num":76},{"id":"lagoa-salgados-silves","t":"Silves won't give up on the Lagoa dos Salgados Natural Reserve","loc":"Silves, Alcantarilha e Pêra, Algarve","reg":"Algarve","cat":"imobiliario","catLabel":"Threatened wetland","est":"acompanhamento","status":"◐ Process moving forward","prazo":false,"verif":"2026-08-21","quem":["Movimento Participativo Lagoa dos Salgados (9 organisations)"],"res":"After more than 20 years of campaigning, ICNF has proposed a 400-hectare Natural Reserve, but the Praia Grande Eco-Resort tourism project still threatens the wetland.","img":"https://causasderaiz.org/lagoa-salgados-silves.jpg?v=1","pet":"","petLabel":"","ll":[37.098,-8.366],"num":77},{"id":"curral-freiras","t":"Cable Car and Adventure Park at Curral das Freiras","loc":"Curral das Freiras, Câmara de Lobos, Madeira Island","reg":"Madeira","cat":"infraestrutura","catLabel":"Tourism in protected area","est":"acompanhamento","status":"◐ Decision challenged","prazo":false,"verif":"2026-08-21","quem":["Quercus-Madeira"],"res":"Quercus-Madeira challenges the decision for not ruling out impact on the critically endangered Zino's petrel.","img":"https://causasderaiz.org/curral-freiras.jpg?v=1","pet":"","petLabel":"","ll":[32.7333,-16.9667],"num":78},{"id":"transvase-tejo-guadiana","t":"Tagus–Guadiana water transfer: CCDR Alentejo studies inter-basin link","loc":"Guadiana basin, Alentejo (link under study with the Tagus river)","reg":"Alentejo","cat":"agua","catLabel":"Inter-basin water transfer","est":"acompanhamento","status":"◐ CCDR Alentejo and EDIA move forward with EU funding bid for study (8 Sep) · ZERO warns of risks","prazo":false,"verif":"2026-09-19","quem":["ZERO"],"res":"The Alentejo Regional Coordination and Development Commission (CCDR) and EDIA met on 8 September to prepare a bid for EU funds to finance an in-depth study on the feasibility of transferring water from the Tagus river to the Guadiana basin, under the national “Água que Une” (\"Water that Unites\") strategy. The scenario under consideration envisages diverting around 150 cubic hectometres of water, which would allow Alqueva-supported irrigation to expand by more than 50,000 new hectares. The environmental association ZERO warns that continuously expanding irrigated area could exhaust the safety reserve the Alqueva reservoir is meant to guarantee in the long run, and that inter-basin transfers tend to generate territorial tensions between donor and recipient regions. The Environment Minister has already downplayed the Tagus–Guadiana link as not \"the first priority\", noting that such a project would require an agreement with Spain. For now there is no green light for construction: the process is solely aimed at securing funding for a technical and economic assessment.","img":"https://causasderaiz.org/transvase-tejo-guadiana.jpg?v=1","pet":"","petLabel":"","ll":null,"num":79},{"id":"verdelago-castro-marim","t":"Verdelago: beach access routed through a resort in Castro Marim","loc":"Verdelago, Castro Marim, Algarve","reg":"Algarve","cat":"praias","catLabel":"Beach access","est":"acompanhamento","status":"◐ APA inspection confirmed conditioned access (Oct 2025)","prazo":false,"verif":"2026-08-21","quem":["Portuguese Environment Agency"],"res":"An APA inspection of 29 Algarve beaches found public access to Verdelago beach, in Castro Marim, conditioned through the interior of a tourism development.","img":"https://causasderaiz.org/verdelago-castro-marim.jpg?v=1","pet":"","petLabel":"","ll":[37.207,-7.475],"num":80},{"id":"castanheira-ribatejo","t":"Vila Franca de Xira wants to triple the Lisbon-North Logistics Platform","loc":"Castanheira do Ribatejo, Vila Franca de Xira","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"acompanhamento","status":"◐ Public consultation closed 4 September · Awaiting strategic environmental assessment","prazo":false,"verif":"2026-09-07","quem":["CDU (Vila Franca de Xira)"],"res":"Vila Franca de Xira City Council approved by majority a detailed plan expanding the Lisbon-North Logistics Platform by around 340 hectares, roughly 300 of them for logistics, technology and data centres. The CDU (Communist coalition) criticised converting about 295 hectares of farmland and ecologically valuable land, estimating €491 million in land-value gains for owners and developers; PSD, IL and Chega raised concerns about the power grid and firefighting capacity. The public consultation closed on 4 September with no outcome announced yet; the council promises a strategic environmental assessment before proceeding.","img":"https://causasderaiz.org/castanheira-ribatejo.jpg?v=1","pet":"","petLabel":"","ll":[38.9575,-8.9731],"num":81},{"id":"mata-albergaria-volta","t":"Tour of Portugal through Mata da Albergaria: Quercus warns of \"serious precedent\" in Gerês","loc":"Mata da Albergaria, Peneda-Gerês National Park, Terras de Bouro","reg":"North","cat":"infraestrutura","catLabel":"Event in protected area","est":"acompanhamento","status":"◐ Stage held on 13 August under conditions · Quercus calls for exclusion in future editions","prazo":false,"verif":"2026-08-24","quem":["Quercus"],"res":"ICNF authorised the 7th stage of the Tour of Portugal cycling race to cross Mata da Albergaria, one of the country's few well-preserved native oak woods, inside Portugal's only National Park. The authorisation imposed strict conditions (no public access, no sound amplification, support vehicles kept to a minimum), but Quercus objected anyway, warning the impacts are not eliminated and that the decision sets a \"serious precedent\"; the association is calling for the route to be excluded from future editions.","img":"https://causasderaiz.org/mata-albergaria-volta.jpg?v=1","pet":"","petLabel":"","ll":[41.746,-8.146],"num":82},{"id":"pszaer","t":"ZAER / PSZAER: over 800 renewable acceleration zones pre-approved without environmental impact assessment","loc":"National: about 170 municipalities, mainly the Algarve, Alentejo and Northeast Trás-os-Montes","reg":"National","cat":"energia","catLabel":"Systemic · ZAER · PSZAER","est":"acompanhamento","status":"◐ ZAER zones pre-approved · Quercus issued unfavourable opinion","prazo":false,"verif":"2026-08-21","quem":["Quercus (\"Black Desert\" opinion)","Plataforma Nordeste Vivo"],"res":"800+ Renewable Energy Acceleration Zones (ZAER) pre-approved in 170 municipalities, exempt from individual EIA. Sectoral Programme for ZAER (PSZAER), Green Map, unfavourable Quercus opinion.","img":"https://causasderaiz.org/pszaer.jpg?v=1","pet":"","petLabel":"","ll":null,"num":83},{"id":"alqueva-solar-flutuante","t":"EDP drops the \"Grande Lago\" floating solar mega-plant on the Alqueva reservoir","loc":"Moura, Portel and Reguengos de Monsaraz, Alqueva reservoir","reg":"Alentejo","cat":"megasolares","catLabel":"Floating solar plant","est":"vitoria","status":"✓ Victory: project cancelled","prazo":false,"verif":"2026-08-21","quem":["Municipalities of Moura, Reguengos de Monsaraz, Portel, Alandroal and Mourão"],"res":"After two years of opposition from five Alentejo municipalities and an unfavourable environmental ruling, EDP abandoned the 154 MW hybrid project on the Alqueva reservoir.","img":"https://causasderaiz.org/alqueva-solar-flutuante.jpg?v=1","pet":"","petLabel":"","ll":[38.2,-7.49],"num":84},{"id":"valtreixal","t":"Valtreixal Mine (Calabor): environmental permit refused","loc":"Calabor, Zamora, a few km from Montesinho Natural Park","reg":"North","cat":"mineracao","catLabel":"Cross-border mining","est":"vitoria","status":"✓ Victory: permit refused","prazo":false,"verif":"2026-08-21","quem":["UIVO Movement"],"res":"Castile and León refused the permit for an open-pit mine a few km from the Portuguese border.","img":"https://causasderaiz.org/valtreixal.jpg?v=1","pet":"","petLabel":"","ll":[41.97,-6.75],"num":85},{"id":"pedreira-cerro-meio-tavira","t":"Cerro do Meio quarry: court orders closure in Tavira over noise and dust","loc":"Cerro do Meio, Luz de Tavira e Santo Estêvão parish, Tavira, Algarve","reg":"Algarve","cat":"mineracao","catLabel":"Quarries","est":"vitoria","status":"✓ Court orders permanent closure · Verdasca Group under police investigation","prazo":false,"verif":"2026-09-07","quem":["Residents of Luz de Tavira e Santo Estêvão"],"res":"The Tavira court ordered the immediate and permanent closure of the Cerro do Meio quarry, for violating the personality rights of residents of the Luz de Tavira e Santo Estêvão parish union. The operation, run by Miner Blanc (part of the Verdasca Group), had been reactivated in 2025 after 12 years suspended, and complaints of excessive noise, vibration and dust multiplied since then; the company now risks disobedience proceedings and a €2,000 fine for each day of non-compliance. The Verdasca Group is also a target of the Judicial Police's \"Terra Limpa\" operation, investigating suspected environmental crimes and corruption linked to another of its companies, in Ourém.","img":"https://causasderaiz.org/pedreira-cerro-meio-tavira.jpg?v=1","pet":"","petLabel":"","ll":[37.107,-7.629],"num":86,"cat2":"poluicao","kw":["noise","noise pollution","dust","air pollution","vibration","environmental pollution"]},{"id":"fanal-madeira","t":"Fanal: grazing and overtourism threaten centuries-old forest","loc":"Fanal, Madeira Natural Park, Porto Moniz","reg":"Madeira","cat":"sistemico","catLabel":"Overtourism in a protected area","est":"acompanhamento","status":"◐ Quercus reports grazing and trampling · Government recommends alternative routes","prazo":false,"verif":"2026-09-14","quem":["Quercus – Madeira Regional Branch"],"res":"Fanal is a Rest and Silence Zone within Madeira Natural Park, known for its centuries-old til trees. Quercus reports that cattle grazing freely devour the trees' new shoots, and that excessive visitor numbers compact the soil and expose roots, with no carrying capacity or marked trails defined by the Institute of Forests and Nature Conservation (IFCN). The Regional Government acknowledged the problem and recommended alternative routes to tour operators, but the association considers the measure insufficient.","img":"https://causasderaiz.org/fanal-madeira.jpg?v=1","pet":"","petLabel":"","ll":[32.7847,-17.113],"num":87},{"id":"porto-santo-areia","t":"Porto Santo: beach loses sand because of the Shelter Port","loc":"Vila Baleira, Porto Santo Island, Madeira","reg":"Madeira","cat":"praias","catLabel":"Coastal erosion","est":"acompanhamento","status":"◐ Dredging works underway · sediment deposited near the beach with no known analysis","prazo":false,"verif":"2026-09-14","quem":["Porto Santo residents"],"res":"Porto Santo's beach, one of the longest in Europe, has repeatedly lost sand since the Shelter Port was built, which interrupts the natural flow of sediment along the coast. In September 2026, dredging works at the marina removed dark sand from the seabed and deposited it a few metres from the beach, in a Blue Flag-classified area, without the laboratory analysis required by law before depositing port sediment being made public.","img":"https://causasderaiz.org/porto-santo-areia.jpg?v=1","pet":"","petLabel":"","ll":[33.0642,-16.3399],"num":88},{"id":"mineracao-mar-profundo-acores","t":"Moratorium on deep-sea mining in Azorean waters","loc":"Waters under the management of the Autonomous Region of the Azores","reg":"Azores","cat":"mineracao","catLabel":"Deep-sea mining","est":"vitoria","status":"✓ Legal moratorium until 2050 · Law 36/2025 enacted","prazo":false,"verif":"2026-09-14","quem":["Sciaena","ANP|WWF","OMA – Azores Ocean Observatory","ZERO"],"res":"Environmental organisations warned that deep-sea mining is \"highly threatening\" to the marine biodiversity of the Azores, home to hydrothermal fields and deep-sea endemic species. After the Azores Legislative Assembly recommended a moratorium in 2023, Portugal's national Parliament passed Law 36/2025 in March 2025, banning deep-sea mining in all waters under Portuguese jurisdiction, including the Azores, until 1 January 2050. Portugal became the first country in the world with a legally binding moratorium on this activity.","img":"https://causasderaiz.org/mineracao-mar-profundo-acores.jpg?v=1","pet":"","petLabel":"","ll":[37.7412,-25.6756],"num":89},{"id":"prospecao-valongo-2","t":"Valongo 2: mining prospecting threatens the Serra da Nogueira and Montesinho Natural Park","loc":"Serra da Nogueira, Bragança and Vinhais municipalities, Bragança district","reg":"North","cat":"mineracao","catLabel":"Mining prospecting","est":"acompanhamento","status":"◐ Public consultation closed with 886 submissions · ICNF and town councils issue unfavourable opinions","prazo":false,"verif":"2026-09-14","quem":["UIVO Movement"],"res":"The company GMR - Consultores has asked Portugal's Directorate-General for Energy and Geology for prospecting and research rights over nickel, cobalt, copper and platinum-group deposits across a 105 km2 area covering the northern slope of the Serra da Nogueira, between Bragança and Vinhais, overlapping the Natura 2000 Network and the UNESCO-recognised Transboundary Biosphere Reserve of Meseta Ibérica. The ICNF and the Bragança and Vinhais town councils issued unfavourable opinions; the public consultation gathered 886 submissions.","img":"https://causasderaiz.org/prospecao-valongo-2.jpg?v=1","pet":"","petLabel":"","ll":[41.75,-6.82],"num":90},{"id":"prospecao-revelhe","t":"Revelhe: mining prospecting request in Montesinho Natural Park","loc":"Santalha, Tuizelo and other parishes of Vinhais, Bragança district","reg":"North","cat":"mineracao","catLabel":"Mining prospecting","est":"acompanhamento","status":"◐ Public consultation closed with 157 submissions · ICNF and town councils issue unfavourable opinions","prazo":false,"verif":"2026-09-14","quem":["UIVO Movement"],"res":"The same company, GMR - Consultores, is asking for prospecting and research rights over gold, silver, copper, lead and zinc deposits across a 37.8 km2 area in five parishes of Vinhais, inside Montesinho Natural Park and the UNESCO-recognised Transboundary Biosphere Reserve of Meseta Ibérica. The ICNF and the Bragança and Vinhais town councils issued unfavourable opinions; the public consultation gathered 157 submissions.","img":"https://causasderaiz.org/prospecao-revelhe.jpg?v=1","pet":"","petLabel":"","ll":[41.72,-7.03],"num":91},{"id":"up12-albandeira","t":"UP12: a 1,030-bed resort threatens Albandeira's last wild coastline","loc":"Praia de Albandeira, Caramujeira, Porches, Lagoa municipality, Algarve","reg":"Algarve","cat":"imobiliario","catLabel":"Coastal tourism development","est":"tribunal","status":"⚡ STOP UP12's court injunction has blocked the Albandeira detailed plan since 23 January 2026","prazo":false,"verif":"2026-09-23","quem":["STOP UP12 Movement"],"res":"The civic group STOP UP12 has fought since 2023 against the UP12 tourism development, which plans 1,030 beds in hotels, aparthotels and villas on the last stretch of wild coastline between Praia da Marinha and Nossa Senhora da Rocha, in Lagoa. The detailed plan for ATE A1 was rejected by the APA, ICNF, CCDR-Algarve and DGT over serious flaws in the environmental assessment, but Lagoa Council reopened a new process to revive it in October 2025, even though the mayor himself admitted that approving this development back in 2008 \"was a mistake\".","img":"https://causasderaiz.org/up12-albandeira.jpg?v=1","pet":"","petLabel":"","ll":[37.0958,-8.428],"num":92},{"id":"muda-defesa-arvores","t":"MUDA: against tree felling and poor management of urban tree cover","loc":"Greater Lisbon, with nationwide action","reg":"National","cat":"arvoredo","catLabel":"Urban tree cover","est":"urgente","status":"⚡ Active petition · 1,723 signatures · survey of councils breaching Law 59/2021","prazo":false,"verif":"2026-09-15","quem":["MUDA"],"res":"MUDA is a citizens' collective, independent of political parties and authorities, that campaigns for the protection of trees and urban tree cover on climate, biodiversity and quality of life grounds. It launched a nationwide petition against the mass felling of trees by Infraestruturas de Portugal along roads and railways, including inside Sintra-Cascais Natural Park, often in breach of Law 59/2021, which sets the legal framework for urban tree management. Beyond the petition, it met with Sintra Council, contacted parliamentary groups, carried out direct action on the ground and surveyed councils breaching the law, identifying specific cases in Cabeço de Vide, Amadora, Sintra, Lisbon and Silves.","img":"https://causasderaiz.org/muda-defesa-arvores.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT120154","petLabel":"⚡ Sign the petition →","ll":[38.79,-9.383],"num":93},{"id":"sintra-sem-herbicidas","t":"Sintra sem Herbicidas: against glyphosate use in public spaces","loc":"Sintra municipality","reg":"Lisbon and Tagus Valley","cat":"poluicao","catLabel":"Pollution","est":"acompanhamento","status":"⚡ Petition archived with no change to the law; movement launches mailing campaign to public bodies (Sep 2026)","prazo":false,"verif":"2026-09-23","quem":["Sintra sem Herbicidas"],"res":"Sintra sem Herbicidas is a citizens' movement active since 2015 campaigning to end the use of herbicides, glyphosate in particular, for weed control in public spaces across Sintra municipality. It filed a petition to the Portuguese Parliament for a ban on dangerous herbicides in urban public spaces, which was heard by the Agriculture and Fisheries Committee, and secured a motion passed by the Colares parish assembly in April 2026 demanding an end to glyphosate use. The group has documented and reported to Sintra Council and to GNR-SEPNA cases of herbicide applied near watercourses and schools, even after the council publicly committed to stopping the practice, and took part in public consultations on the national action plans for pollinators and for the sustainable use of pesticides.","img":"https://causasderaiz.org/sintra-sem-herbicidas.jpg?v=1","pet":"","petLabel":"","ll":[38.7979,-9.3904],"num":94},{"id":"aterro-barlavento","t":"Barlavento Landfill: residents protest against smell, flies and expansion","loc":"Porto de Lagos, Portimão municipality, bordering Silves","reg":"Algarve","cat":"poluicao","catLabel":"Waste management","est":"urgente","status":"⚡ Residents protest against smell and flies · Algar wants to expand with new Cell E · ZERO accuses it of breaching organic waste law","prazo":false,"verif":"2026-09-16","quem":["Associação de Moradores de Odelouca, Porto de Lagos e Rasmalho","Ação Ambiental para o Barlavento","ZERO"],"res":"The Barlavento Sanitary Landfill, in Porto de Lagos, Portimão municipality, is close to maximum capacity and causing unbearable smell and swarms of flies in Odelouca, Porto de Lagos and Rasmalho. On 12 March 2026, the Associação de Moradores de Odelouca, Porto de Lagos e Rasmalho (residents' association) organised a protest outside the landfill, covered by national broadcaster RTP and the local press. Instead of considering closure, Algar, the company that runs the multi-municipal waste system for the Algarve's 16 municipalities, plans to expand the site with a new cell (Cell E, around 98,900 m², capacity for 150,000 tonnes a year). In November 2025, environmental association ZERO accused Algar of continuing to dump untreated organic waste, around 40% of what enters the landfill, a practice banned under Decree-Law 24/2024; according to Algar's own environmental impact study, the landfill is responsible for 55% of greenhouse gas emissions in Portimão municipality. In 2024, Algar also tried to expropriate land in Silves for the expansion, but Silves Municipal Council unanimously opposed it, echoing the popular opposition that had already blocked a similar attempt in 1995.","img":"https://causasderaiz.org/aterro-barlavento.jpg?v=1","pet":"","petLabel":"","ll":[37.2107,-8.5453],"num":95,"kw":["landfill","waste","air pollution","smell","flies","expansion","organic waste","emissions"]},{"id":"pinhal-freiras-seixal","t":"Pinhal das Freiras: urban development plan threatens the Fernão Ferro/Lagoa de Albufeira conservation area","loc":"Pinhal das Freiras, Mata de Belverde, Seixal municipality","reg":"Lisbon and Tagus Valley","cat":"imobiliario","catLabel":"Land-use planning","est":"urgente","status":"⚡ Petition with 7,700 signatures delivered to Parliament, rapporteur appointed · Seixal Council approved 2.5 million m² urban development plan · Protest outside the council offices on 1 September 2026","prazo":false,"verif":"2026-09-16","quem":["Seixal+Verde","Movimento Salvar a Floresta do Seixal"],"res":"The Pinhal das Freiras, in Mata de Belverde, Seixal municipality, is part of the Fernão Ferro/Lagoa de Albufeira Special Conservation Area, protected under the Natura 2000 network since 2000. In August 2024, Seixal Municipal Council approved a 2.5 million m² urban development plan for the area, excluding green spaces, with buildings up to 19 metres tall; the Salvar a Floresta do Seixal movement estimates the loss of around 50,000 trees, 2.5 km² of forest and 200 km of trails and cycle paths, with capacity foreseen for more than 90,000 new residents. In March 2025, residents formalised the environmental association Seixal+Verde, which launched a petition to the Portuguese Parliament against the project, delivered with more than 7,700 signatures; the petition (no. 166/XVII/1) was admitted, with a rapporteur appointed in June 2026, and awaits review by the Environment and Energy Committee. The association met with Seixal Municipal Council in 2025 and 2026 and organised a protest outside the council offices on 1 September 2026.","img":"https://causasderaiz.org/pinhal-freiras-seixal.jpg?v=1","pet":"","petLabel":"","ll":[38.615,-9.093],"num":96,"kw":["urban development","Natura 2000","deforestation","Special Conservation Area","petition","land-use planning"]},{"id":"eolicas-serra-ossa","t":"No to Wind Turbines on Serra d'Ossa: petition against wind farm in Central Alentejo","loc":"Serra d'Ossa, Central Alentejo (Estremoz, Redondo, Borba, Vila Viçosa and Alandroal)","reg":"Alentejo","cat":"eolicas","catLabel":"Wind farm","est":"urgente","status":"⚡ Petition with more than 430 signatures within days · Calls on Estremoz Council and the Government to halt the project · An earlier project already failed to get approval for measurement towers","prazo":false,"verif":"2026-09-16","quem":["Petition signatories"],"res":"A public petition calls for a wind farm project on Serra d'Ossa, in Central Alentejo, to be halted, and for the mountain range to be classified as a protected area.","img":"https://causasderaiz.org/eolicas-serra-ossa.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT132905","petLabel":"⚡ Sign the petition →","ll":[38.733,-7.533],"num":97},{"id":"amianto-vale-milhacos-seixal","t":"Asbestos at the Vale de Milhaços primary school, Seixal","loc":"Vale de Milhaços, Corroios parish, Seixal municipality","reg":"Lisbon and Tagus Valley","cat":"comunidade","catLabel":"Community","est":"urgente","status":"⚡ Union gave the Ministry of Education until 13 April 2026 to respond; protest at Seixal City Council planned for 22 April","prazo":false,"verif":"2026-09-23","quem":["S.TO.P., Sindicato de Todos os Profissionais da Educação"],"res":"Over a hundred education professionals from the Vale de Milhaços school group in Seixal protested in March 2026, closing more than half of the group's 10 schools, demanding removal of the asbestos plates still present at the main school and more support staff.","img":"https://causasderaiz.org/amianto-vale-milhacos-seixal.jpg?v=1","pet":"","petLabel":"","ll":[38.6386,-9.1329],"num":98,"cat2":"poluicao","kw":["asbestos","school health","environmental pollution"]},{"id":"rio-lis-poluicao","t":"Pollution of the Lis river basin: untreated sewage discharges, no lasting solution in sight","loc":"Lis river basin, Leiria and Marinha Grande municipalities","reg":"Centre","cat":"agua","catLabel":"Water","est":"urgente","status":"⚡ Claimants seek €256,000 in damages after a 2025 discharge of up to 25,000 m³ of raw sewage; Oikos confirms a pollution hotspot on the Lena river in 2026","prazo":false,"verif":"2026-09-23","quem":["Águas do Centro Litoral","Oikos, Associação de Defesa do Ambiente e do Património da Região de Leiria","Marinha Grande City Council","Portuguese Environment Agency"],"res":"In August 2025, a breakdown at the Monte Real pumping station, run by Águas do Centro Litoral, forced a discharge of between 20,000 and 25,000 m³ of raw sewage into the Lis river, with swimming banned at Vieira Beach; in August 2026, 12 claimants are seeking €256,000 in damages, and the Oikos association confirmed, in September 2026 tests, a pollution hotspot on the Lena river, a Lis tributary, in urban Leiria.","img":"https://causasderaiz.org/rio-lis-poluicao.jpg?v=1","pet":"","petLabel":"","ll":[39.8281,-8.9407],"num":99,"cat2":"poluicao","kw":["water pollution","sanitation","sewage"]},{"id":"aterro-castelo-branco-biosmart","t":"Expansion of the BioSmart industrial waste landfill, Castelo Branco","loc":"Vedulho de Baixo, Castelo Branco municipality","reg":"Centre","cat":"poluicao","catLabel":"Pollution","est":"urgente","status":"⚡ ZERO says the project is \"clearly illegal\"; consultation closed, under review at CCDR Centro","prazo":false,"verif":"2026-09-23","quem":["ZERO","Portuguese Environment Agency","CCDR Centro"],"res":"BioSmart, Soluções Ambientais, S.A. wants to expand the Castelo Branco non-hazardous industrial waste landfill with a third cell, raising total capacity from 488,750 to 639,250 tonnes. The ZERO association issued a negative opinion, arguing the environmental impact study allowed for the possibility of receiving organic waste, whose landfill deposition has been banned by law since 2026, and is asking CCDR Centro not to license the new cell.","img":"https://causasderaiz.org/aterro-castelo-branco-biosmart.jpg?v=1","pet":"","petLabel":"","ll":[39.803,-7.56],"num":101,"kw":["waste","soil pollution","water pollution"]},{"id":"aterro-lustosa-lousada","t":"Lustosa landfill, Lousada: reconfiguration in public consultation","loc":"Union of the Lustosa and Barrosas parishes, Lousada municipality","reg":"North","cat":"poluicao","catLabel":"Pollution","est":"consulta","status":"⚡ Lousada City Council opposes the changes; CCDR Norte public consultation until 30 September 2026","prazo":true,"verif":"2026-09-23","quem":["Lousada Municipal Council","RIMA","Bloco de Esquerda"],"res":"The Lustosa non-hazardous industrial waste landfill, run by RIMA (a company jointly held by Mota-Engil Ambiente, SUMA, Lousada Municipality and IDAMBI), is in a CCDR Norte public consultation until 30 September 2026 over a cell reconfiguration project, including a new cell 2. Lousada Municipal Council opposes the changes; the landfill has previously drawn controversy for receiving industrial waste imported from Italy.","img":"https://causasderaiz.org/aterro-lustosa-lousada.jpg?v=1","pet":"","petLabel":"","ll":[41.2814,-8.2934],"num":102,"kw":["waste","soil pollution"]},{"id":"hotel-vale-olival-armacao-pera","t":"50-million-euro hotel in Vale do Olival, Armação de Pêra","loc":"Vale do Olival, Armação de Pêra, Silves municipality, Algarve","reg":"Algarve","cat":"imobiliario","catLabel":"Tourism in sensitive coastal area","est":"urgente","status":"⚡ Construction underway on an unstable cliff; petition with hundreds of signatures","prazo":false,"verif":"2026-09-23","quem":["Armação de Pêra residents","Public petition"],"res":"Silves Municipal Council issued, on 3 December 2025, the building permit for a four-star hotel with 250 rooms and capacity for 500 guests, a 50-million-euro investment, on one of the last vacant beachfront plots in Armação de Pêra. The land sitting on an unstable cliff sparked strong backlash on social media and a public petition; the council held an information session in December, but construction has continued.","img":"https://causasderaiz.org/hotel-vale-olival-armacao-pera.jpg?v=1","pet":"https://peticaopublica.com/pview.aspx?pi=PT128984","petLabel":"⚡ Sign the petition →","ll":[37.1027,-8.3547],"num":103},{"id":"poluicao-rio-tejo-protejo","t":"proTEJO reports new resurgence of pollution in the Tagus river","loc":"From the Upper Tagus (Vila Velha de Ródão) to Chamusca, in the Tagus Lezíria","reg":"Centre","cat":"poluicao","catLabel":"River pollution","est":"urgente","status":"⚡ proTEJO demands urgent testing and accountability for polluters (Jun 2026)","prazo":false,"verif":"2026-09-23","quem":["proTEJO – Movement for the Tagus"],"res":"The proTEJO movement reported, in June 2026, a resurgence of pollution in the Tagus river between Vila Velha de Ródão and Chamusca, with abundant foam and darkened waters, a pattern the movement has documented for over a decade and attributes to industrial and urban effluent discharges along the Upper Tagus. proTEJO is demanding that the Portuguese Environment Agency and IGAMAOT carry out full water tests, conduct night-time inspections of discharges, and suspend effluent discharge licences in cases of non-compliance.","img":"https://causasderaiz.org/poluicao-rio-tejo-protejo.jpg?v=1","pet":"","petLabel":"","ll":[39.6494,-7.6667],"num":104,"cat2":"agua","kw":["water pollution","industrial effluent"]}];

